INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(451953, 41981, 714, '<td valign="top">I really like how clean this looks.  The colors are wonderful and looks very appitizing. vote 10</td>', 'I really like how clean this looks.  The colors are wonderful and looks very appitizing. vote 10', '2003-10-16 01:06:53.000000', NULL, 1),
(451954, 42467, 6597, '<td valign="top">good composition The different colors make this a strong photo.  the colors blend together so well.      9</td>', 'good composition The different colors make this a strong photo.  the colors blend together so well.      9', '2003-10-16 01:07:38.000000', NULL, 1),
(451955, 42440, 714, '<td valign="top">Not a bad shot, really!  The background just takes away the wow.  Maybe try a white background.</td>', 'Not a bad shot, really!  The background just takes away the wow.  Maybe try a white background.', '2003-10-16 01:08:28.000000', NULL, 1),
(451956, 42452, 12617, '<td valign="top">Just a personal prefrence.<br/>I think it would''ve been better if the table/cloth and fork was clean.<br/>otherwise I like the way its taken.</td>', 'Just a personal prefrence.I think it would''ve been better if the table/cloth and fork was clean.otherwise I like the way its taken.', '2003-10-16 01:09:51.000000', NULL, 1),
(451957, 42411, 714, '<td valign="top">Very nice shot. The only thing that bugs me is the green plant in the forground. Other wise..very nice.</td>', 'Very nice shot. The only thing that bugs me is the green plant in the forground. Other wise..very nice.', '2003-10-16 01:10:00.000000', NULL, 1),
(451958, 41995, 6008, '<td valign="top">Lots of color, but maybe just a little too busy. The eyes are wandering looking for a focus and it''s hard to stop on just one thing, even though the hens are obviously the main attraction. It looks like a big family feast, and a lot of work went into both the preparation and the presentation of the shot. The angle isnt bad, and I could see this accompanying the recipe, I just think it needed to be a little less cluttered.</td>', 'Lots of color, but maybe just a little too busy. The eyes are wandering looking for a focus and it''s hard to stop on just one thing, even though the hens are obviously the main attraction. It looks like a big family feast, and a lot of work went into both the preparation and the presentation of the shot. The angle isnt bad, and I could see this accompanying the recipe, I just think it needed to be a little less cluttered.', '2003-10-16 01:10:11.000000', NULL, 1),
(451960, 42427, 714, '<td valign="top">I can''t wait to hear how to make this.  Sounds interesting, yet fun.</td>', 'I can''t wait to hear how to make this.  Sounds interesting, yet fun.', '2003-10-16 01:11:02.000000', NULL, 1),
(451962, 41981, 4338, '<td valign="top">Very nicely done... looks VERY good</td>', 'Very nicely done... looks VERY good', '2003-10-16 01:11:45.000000', NULL, 1),
(451964, 42074, 714, '<td valign="top">oh very nice!  I could have done without the forks in the shot. Great lighting and background. vote 8</td>', 'oh very nice!  I could have done without the forks in the shot. Great lighting and background. vote 8', '2003-10-16 01:13:21.000000', NULL, 1),
(451965, 42472, 6008, '<td valign="top">I made some of these cookies this evening too! Wonderfully easy recipe. The color of the cookies is good, although the light on them seems a little uneven with more on the front than the back, which also makes the peanut butter container a little in the shadow too. Compositionally it doesnt really feel that balanced, perhaps it is the jug that''s throwing it off some. The angle on the cookies is good, although it looks a little off on the containers.</td>', 'I made some of these cookies this evening too! Wonderfully easy recipe. The color of the cookies is good, although the light on them seems a little uneven with more on the front than the back, which also makes the peanut butter container a little in the shadow too. Compositionally it doesnt really feel that balanced, perhaps it is the jug that''s throwing it off some. The angle on the cookies is good, although it looks a little off on the containers.', '2003-10-16 01:13:54.000000', NULL, 1),
(451966, 42231, 10084, '<td valign="top">I like how each item on the countertop seems to have a spotlight on it. Looks very appetizing. Not too sure about the color of the frame, but otherwise a pretty good shot. Can''t wait to see the receipe.</td>', 'I like how each item on the countertop seems to have a spotlight on it. Looks very appetizing. Not too sure about the color of the frame, but otherwise a pretty good shot. Can''t wait to see the receipe.', '2003-10-16 01:14:12.000000', NULL, 1),
(451967, 42381, 6202, '<td valign="top">very cute.  Definately different for the challenge.   Nice photograph of the chipmunk.</td>', 'very cute.  Definately different for the challenge.   Nice photograph of the chipmunk.', '2003-10-16 01:14:36.000000', NULL, 1),
(451969, 42409, 9411, '<td valign="top">Looks tasty, but I find the image way too busy. Something needed to not be there, either the background or the patterned plate and bowl. Everything is getting lost.</td>', 'Looks tasty, but I find the image way too busy. Something needed to not be there, either the background or the patterned plate and bowl. Everything is getting lost.', '2003-10-16 01:15:20.000000', NULL, 1),
(451971, 42100, 714, '<td valign="top">Simple, colorful and very nice.  Looks good to eat.  vote 8</td>', 'Simple, colorful and very nice.  Looks good to eat.  vote 8', '2003-10-16 01:16:22.000000', NULL, 1),
(451972, 42437, 4338, '<td valign="top">not sure if you used a flash, but i feel a bounced flash would have brightned up the image a little and possibly sharpened up the image a little more</td>', 'not sure if you used a flash, but i feel a bounced flash would have brightned up the image a little and possibly sharpened up the image a little more', '2003-10-16 01:17:18.000000', NULL, 1),
(451973, 42447, 9411, '<td valign="top">Wow, very elaborate. Nice carry through on the theme, Just a little bright.</td>', 'Wow, very elaborate. Nice carry through on the theme, Just a little bright.', '2003-10-16 01:17:27.000000', NULL, 1),
(451974, 42409, 714, '<td valign="top">The light is really bright and the background is really busy.  Looks pretty good though. Good luck.</td>', 'The light is really bright and the background is really busy.  Looks pretty good though. Good luck.', '2003-10-16 01:18:16.000000', NULL, 1),
(451975, 42028, 10084, '<td valign="top">Great depth of field. The green glass really adds a great touch of color to the shot and helps the main subject pop out of the shot. I like how you were able to capture the shadows of the cream , gives it fluffiness. I also like how you sprinkled the powder sugar(?) in on the plate .</td>', 'Great depth of field. The green glass really adds a great touch of color to the shot and helps the main subject pop out of the shot. I like how you were able to capture the shadows of the cream , gives it fluffiness. I also like how you sprinkled the powder sugar(?) in on the plate .', '2003-10-16 01:18:59.000000', NULL, 1),
(451978, 42294, 6008, '<td valign="top">It''s a little dark and seems a little soft for that reason. Placing elements in the center of the photo can work sometimes, but I think in this instance it doesnt really add that much. There doesnt appear to be much happening, it''s just there, and not really very appetizing. Perhaps a more dramatic light and a tighter crop could have improved it some.</td>', 'It''s a little dark and seems a little soft for that reason. Placing elements in the center of the photo can work sometimes, but I think in this instance it doesnt really add that much. There doesnt appear to be much happening, it''s just there, and not really very appetizing. Perhaps a more dramatic light and a tighter crop could have improved it some.', '2003-10-16 01:21:09.000000', NULL, 1),
(451979, 42419, 4338, '<td valign="top">great shot!!!!</td>', 'great shot!!!!', '2003-10-16 01:21:13.000000', NULL, 1),
(451983, 42098, 714, '<td valign="top">Boy, look at all that color.  Very nice, but maybe a bit over done.  I bet you really enjoyed this. mmm...</td>', 'Boy, look at all that color.  Very nice, but maybe a bit over done.  I bet you really enjoyed this. mmm...', '2003-10-16 01:22:10.000000', NULL, 1),
(451984, 41523, 10084, '<td valign="top">Great sharpness and depth of field in the shot. Beautiful reflections on the glass. The red color really helps to bring your eyes to the glass. The background is also quite interesting but not overwhelm the foreground.</td>', 'Great sharpness and depth of field in the shot. Beautiful reflections on the glass. The red color really helps to bring your eyes to the glass. The background is also quite interesting but not overwhelm the foreground.', '2003-10-16 01:22:19.000000', NULL, 1),
(451985, 42467, 714, '<td valign="top">This is one of my favorites. Very nice! Vote 10</td>', 'This is one of my favorites. Very nice! Vote 10', '2003-10-16 01:23:27.000000', NULL, 1),
(451988, 41984, 4338, '<td valign="top">I like the arrangement, however a lower camera angle and some different lighting would have made it more interesting</td>', 'I like the arrangement, however a lower camera angle and some different lighting would have made it more interesting', '2003-10-16 01:24:50.000000', NULL, 1),
(451989, 42384, 714, '<td valign="top">I love this shot. Way out of the ordinary.  I like the whole set up. Vote10</td>', 'I love this shot. Way out of the ordinary.  I like the whole set up. Vote10', '2003-10-16 01:25:19.000000', NULL, 1),
(451990, 42370, 10084, '<td valign="top">Beautiful vivid colors helps to give great interest to the shot. I like how you added the drops of yellow and red onto the plate to give it an extra bit of color. Looks very eddible and tasty.</td>', 'Beautiful vivid colors helps to give great interest to the shot. I like how you added the drops of yellow and red onto the plate to give it an extra bit of color. Looks very eddible and tasty.', '2003-10-16 01:25:31.000000', NULL, 1),
