(452587, 42370, 656, '<td valign="top">a bit brighter exposure would have really helped the white background stay white and not expose as grey.  Food looks excellent.</td>', 'a bit brighter exposure would have really helped the white background stay white and not expose as grey.  Food looks excellent.', '2003-10-16 12:58:42.000000', NULL, 1),
(452591, 42447, 10673, '<td valign="top">Excellent...looks YUMMY!!!  10</td>', 'Excellent...looks YUMMY!!!  10', '2003-10-16 13:01:59.000000', NULL, 1),
(452604, 42433, 12966, '<td valign="top">The sense of tradition, old memories, lavander scent and fragrance of the fresh bread are all well rendered in the picture. I like the focus.</td>', 'The sense of tradition, old memories, lavander scent and fragrance of the fresh bread are all well rendered in the picture. I like the focus.', '2003-10-16 13:07:44.000000', NULL, 1),
(452626, 42411, 10437, '<td valign="top">This tastes like august in Sweden! Yummy yummy!<br/>Thank you for bringing back summer memories 10:-)<br/>Like the DOF, it is almost like the Beast is stirring at me!<br/></td>', 'This tastes like august in Sweden! Yummy yummy!Thank you for bringing back summer memories 10:-)Like the DOF, it is almost like the Beast is stirring at me!', '2003-10-16 13:19:23.000000', NULL, 1),
(452628, 42028, 10437, '<td valign="top">As beautiful as it must taste!</td>', 'As beautiful as it must taste!', '2003-10-16 13:20:29.000000', NULL, 1),
